<?php

declare(strict_types=1);namespace Acorn\SafetyHealthcheck\Admin;use Acorn\SafetyHealthcheck\Database\Schema;
final class DashboardPage{public function render():void{if(!current_user_can('manage_acorn_healthcheck'))wp_die('Forbidden',403);global$wpdb;$a=Schema::table('assessments');$ans=Schema::table('answers');$metrics=['Starts'=>(int)$wpdb->get_var("SELECT COUNT(*) FROM $a"),'Assessed / completed'=>(int)$wpdb->get_var("SELECT COUNT(*) FROM $a WHERE status IN ('assessed','completed')"),'Report captures'=>(int)$wpdb->get_var("SELECT COUNT(*) FROM $a WHERE status='completed'"),'Audit requests'=>(int)$wpdb->get_var('SELECT COUNT(*) FROM '.$a.' a JOIN '.Schema::table('contacts').' c ON c.id=a.contact_id WHERE c.audit_requested=1')];$findings=$wpdb->get_results("SELECT question_key,COUNT(*) total FROM $ans WHERE finding_status IN ('review','priority') GROUP BY question_key ORDER BY total DESC LIMIT 10",ARRAY_A);echo'<div class="wrap"><h1>Healthcheck Dashboard</h1><div class="acorn-hc-admin-metrics">';foreach($metrics as$label=>$value)echo'<div><h2>'.esc_html($label).'</h2><strong>'.(int)$value.'</strong></div>';echo'</div><h2>Common findings</h2><ol>';foreach($findings as$f)echo'<li>'.esc_html($f['question_key']).': '.(int)$f['total'].'</li>';echo'</ol><h2>Service opportunities</h2><ul>';foreach(['health_safety','fire','legionella','asbestos']as$tag){$count=(int)$wpdb->get_var($wpdb->prepare("SELECT COUNT(*) FROM $a WHERE service_tags_json LIKE %s",'%"'.$wpdb->esc_like($tag).'"%'));echo'<li>'.esc_html(ucwords(str_replace('_',' ',$tag))).': '.$count.'</li>';}echo'</ul></div>';}}
